#ifndef CEREAL_EXTERNAL_RAPIDJSON_H_
#define CEREAL_EXTERNAL_RAPIDJSON_H_

// Map cereal's prefixed RapidJSON macros onto the packaged headers.

#ifndef CEREAL_RAPIDJSON_NAMESPACE
#define CEREAL_RAPIDJSON_NAMESPACE rapidjson
#endif

#ifndef RAPIDJSON_NAMESPACE
#define RAPIDJSON_NAMESPACE CEREAL_RAPIDJSON_NAMESPACE
#endif

#ifdef CEREAL_RAPIDJSON_ASSERT_THROWS
#ifndef RAPIDJSON_ASSERT_THROWS
#define RAPIDJSON_ASSERT_THROWS
#endif
#endif

#ifdef CEREAL_RAPIDJSON_ASSERT
#ifndef RAPIDJSON_ASSERT
#define RAPIDJSON_ASSERT(x) CEREAL_RAPIDJSON_ASSERT(x)
#endif
#endif

#ifdef CEREAL_RAPIDJSON_WRITE_DEFAULT_FLAGS
#ifndef RAPIDJSON_WRITE_DEFAULT_FLAGS
#define RAPIDJSON_WRITE_DEFAULT_FLAGS CEREAL_RAPIDJSON_WRITE_DEFAULT_FLAGS
#endif
#endif

#ifdef CEREAL_RAPIDJSON_PARSE_DEFAULT_FLAGS
#ifndef RAPIDJSON_PARSE_DEFAULT_FLAGS
#define RAPIDJSON_PARSE_DEFAULT_FLAGS CEREAL_RAPIDJSON_PARSE_DEFAULT_FLAGS
#endif
#endif

#endif
